//! Experimental (V1.1, UI: 实验性) site automation: `accounts.create` and
//! `browser.start_task` through the [`SiteAdapter`] trait, with a [`DemoSiteAdapter`] that
//! drives a plain HTTP-form test site (bundled as `examples/demo_site.rs`).
//!
//! What this is — and is not:
//! * Only **adapted** sites are supported; there is no automation of arbitrary sites and no
//!   real controlled-browser driver in this build (CONTRACTS §8, §15).
//! * The password is generated by the executor from the OS CSPRNG, written to the trusted
//!   client's pending-registration store **before** anything is submitted, and never
//!   returned to the AI (design doc §6.3).
//! * Every request needs an idempotency key. An uncertain outcome becomes `unknown`; a retry
//!   with the same key first checks whether the account exists instead of registering again
//!   (no duplicate sign-ups, no lost accounts).

mod accounts;
mod demo;
pub mod password;

pub use accounts::{
    AccountCreateRequest, AccountCreateResult, AccountCreator, MemoryPendingStore,
    PendingRegistration, PendingRegistrationStore, RegistrationStatus, SignupOutcome,
    SignupProfile, SiteAction, SiteAdapter, SiteAdapterInfo, SiteLogin, SiteTaskResult,
};
pub use demo::DemoSiteAdapter;
